package com.codepilot1c.core.edt.development;
import static org.junit.Assert.*;
import java.util.*;
import org.junit.Test;
public class NativeUiContractTest {
 private Map<String,Object> open(){return new LinkedHashMap<>(Map.of("action","menu_open","snapshot_id","own-snapshot","expected_window","Own form","expected_form","Catalog.Own.Form.Main","ui_backend","window_message_click","capture",true));}
 @Test public void explicitBackendAndExactManagedSourceRequired(){DirectTestClientService.validateAction(open());var noBackend=open();noBackend.remove("ui_backend");assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(noBackend));var noSource=open();noSource.remove("expected_form");assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(noSource));}
 @Test public void nativeParametersCannotLeakIntoLegacyClose(){var a=open();a.put("action","close");assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}
 @Test public void systemCloseNeedsRecordedReturnAndNoManagedDialogClaim(){var a=new LinkedHashMap<String,Object>(Map.of("action","system_dialog_close","snapshot_id","owned-dialog","expected_window","Настройка формы","ui_backend","window_message_close","return_form","Catalog.Own.Form.Main"));DirectTestClientService.validateAction(a);a.put("expected_form","fake");assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}
 @Test public void standaloneNativeSnapshotsCannotBeGuessedInBatch(){var a=new LinkedHashMap<>(open());a.remove("capture");a.remove("snapshot_id");var batch=Map.<String,Object>of("action","batch","snapshot_id","own","expected_window","Own form","steps",List.of(a));assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(batch));}
 @Test public void reportedMenuIntentRoutesToDirectContractWithoutClaimingVisibility(){var p=com.codepilot1c.core.mcp.host.McpRuntimeRouting.choose(Map.of("project","Own","intent","ui","required_actions",List.of("open_more_menu","capture_popup","inspect_menu_items")),true);assertEquals("testclient",p.get("engine"));assertEquals("planned",p.get("state"));assertEquals(false,((Map<?,?>)p.get("header_ui_contract")).get("visibility_proven"));}
 @Test public void summaryRetainsBackendCaptureAndMenuProof(){var full=Map.<String,Object>of("success",true,"native_capture",Map.of("success",false,"state","pending"),"ui_backend","window_message_click","native_ui",Map.of("header_menu_proven",true,"items",List.of("large-details")));var brief=DirectTestClientService.present(full,Map.of("action","menu_open","response_mode","summary"),"operation");assertEquals(full.get("native_capture"),brief.get("native_capture"));assertEquals("window_message_click",brief.get("ui_backend"));assertEquals(true,((Map<?,?>)brief.get("native_ui")).get("header_menu_proven"));assertFalse(((Map<?,?>)brief.get("native_ui")).containsKey("items"));}
}
